head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setRowVisible]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 를 숨깁니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 숨기거나 표시할 Body Row 의 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다.",
        "visible(선택) 파라미터에 true 설정 시 해당 Row 를 GridView 컴포넌트에 표시합니다.",
        "visible(선택) 파라미터에 false 설정 시 해당 Row 를 GridView 컴포넌트에서 숨깁니다.",
        "visible(선택) 파라미터를 생략 시 기본값(false)으로 동작해야 합니다.",
        "Row 가 숨겨지면 RowNum Column 의 Row 순번은 재계산되지 않고 숨겨진 Row 의 순번은 건너뜁니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (6 Row)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true">';
    let arrNames = ['김철수', '이영희', '박민준', '최서연', '정도윤', '강하은'];
    let arrDept = ['영업1팀', '영업2팀', '개발팀', '인사팀', '재무팀', '기획팀'];
    for (var i = 0; i < arrNames.length; i++) {
        strDlt += '<w2:row>';
        strDlt += '<col1><![CDATA[' + (i + 1) + ']]></col1>';
        strDlt += '<col2><![CDATA[' + arrNames[i] + ']]></col2>';
        strDlt += '<col3><![CDATA[' + arrDept[i] + ']]></col3>';
        strDlt += '</w2:row>';
    }
    strDlt += '</w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 조건 설정 - RowNum Column 표시 (@spec 순번 검증용)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
    };

    let cList = $c.gcm.createCList(properties);

    // target 생성
    await scwin.createGrid(cList);
}



// 일반 그리드(custom 셀 불필요) 동적 생성
scwin.createGrid = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="사원 목록"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hcol1" value="사번"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" displayType="label"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" displayType="label"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" displayType="label"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 현재 표시중인 RowNum 순번 목록 수집 (재계산 없이 숨김 순번을 건너뛰는지 확인)
scwin.getDisplayedRowNums = function () {
    let arrNum = [];
    let tdList = document.querySelectorAll("td[id*='target1_headerRowNumber_bodyRow_']");
    for (var i = 0; i < tdList.length; i++) {
        // 화면에 표시된 RowNum 셀만 수집
        if (tdList[i].offsetParent !== null) {
            let txt = tdList[i].textContent.trim();
            if (txt !== '') arrNum.push(txt);
        }
    }
    return arrNum;
}



scwin.btn_setRowVisible_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let visibleStr = par_visible.getText();

    let msg = '';
    if (visibleStr === '') {
        // visible 생략 → 기본값(false) 동작
        target1.setRowVisible(rowIndex);
        msg = "setRowVisible(" + rowIndex + ") [visible 생략]";
    } else {
        let visBool = visibleStr === 'true';
        target1.setRowVisible(rowIndex, visBool);
        msg = "setRowVisible(" + rowIndex + ", " + visBool + ")";
    }

    // 적용 결과 확인 : getRowVisible + 표시중인 RowNum 순번
    //  ※ setRowVisible 후 그리드 재렌더가 비동기로 일어나므로, RowNum 은 setTimeout 으로 재렌더 후 읽어야 최신(숨김 반영) 값이 출력됨
    let isVisible = target1.getRowVisible(rowIndex);
    setTimeout(function () {
        let arrNum = scwin.getDisplayedRowNums();
        wf_body_bottom.getObj("scwin").setReturnValue(msg + "\n[getRowVisible(" + rowIndex + ")] " + isVisible + "\n[표시중 RowNum 순번] " + arrNum.join(', '));
    }, 300);
}
